SELECT id, order_id, carrier, shipped_date, delivered_date, cost, status, PERCENT_RANK() OVER (ORDER BY cost) AS cost_percent_rank, ROW_NUMBER() OVER (PARTITION BY status ORDER BY delivered_date DESC, id) AS seq_no, ROUND(cost / SUM(cost) OVER (PARTITION BY carrier), 4) AS cost_share, FIRST_VALUE(cost, TRUE) OVER w_running AS first_known_cost, ROW_NUMBER() OVER (ORDER BY shipped_date DESC, id) AS event_seq FROM shipments WINDOW w_running AS (PARTITION BY status ORDER BY cost, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
